function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // parent
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 50);
  ctx.lineTo(W/2 - 80, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();

  // child
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 30 * Math.sin(t), H/2, 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 30 * Math.sin(t), H/2 + 15);
  ctx.lineTo(W/2 + 50 + 30 * Math.sin(t), H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 30 * Math.sin(t), H/2 + 40);
  ctx.lineTo(W/2 + 30 + 30 * Math.sin(t), H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 30 * Math.sin(t), H/2 + 40);
  ctx.lineTo(W/2 + 70 + 30 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  // arms around
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + 70);
  ctx.quadraticCurveTo(W/2, H/2 + 50 + 10 * Math.sin(t), W/2 + 30 + 30 * Math.sin(t), H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 80, H/2 + 70);
  ctx.quadraticCurveTo(W/2 - 60, H/2 + 50 + 10 * Math.sin(t), W/2 + 30 + 30 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  ctx.restore();
}
